import re
from pathlib import Path

def rewrite(text: str) -> str:
    text = text.replace(
        'option go_package = "github.com/sandbox-kit/kit/sdks/go/sandbox;sandbox";',
        'option go_package = "github.com/sandbox-kit/kit/sdks/go/contracts/kit/sandbox/v1;sandboxv1";',
    )
    lines = text.splitlines(keepends=True)
    decl = re.compile(r'^(message|enum) (\w+)')
    for i, line in enumerate(lines):
        match = decl.match(line)
        if not match:
            continue
        name = match.group(2)
        j = i - 1
        while j >= 0 and lines[j].strip() == "":
            j -= 1
        end = j
        while j >= 0 and lines[j].lstrip().startswith("//"):
            j -= 1
        start = j + 1
        if start > end:
            continue
        first = lines[start]
        if name in first:
            continue
        prefixed = re.match(r'^(\s*// )([a-z].*)$', first)
        if prefixed:
            lines[start] = f"{prefixed.group(1)}{name} {prefixed.group(2)}"
    rewritten = []
    for line in lines:
        fragment = re.match(r'^(\s*// )is ([a-z])(.*)$', line)
        if fragment:
            line = f"{fragment.group(1)}{fragment.group(2).upper()}{fragment.group(3)}"
        rewritten.append(line)
    return "".join(rewritten)

